uniform float amzp_rippleDecay;
uniform float amzp_rippleSpeed;
uniform float amzp_aspectX;
uniform float amzp_aspectY;
uniform float amzp_chromaWarp;
uniform float amzp_edgeMode;
uniform float amzp_globalMix;
    float2 applyEdge(float2 uv, float mode) {
        if (mode < 1.5) return uv;
        if (mode < 2.5) return fract(uv);
        if (mode < 3.5) {
            float2 r = uv;
            r.x = (mod(floor(r.x), 2.0) == 0.0) ? fract(r.x) : 1.0 - fract(r.x);
            r.y = (mod(floor(r.y), 2.0) == 0.0) ? fract(r.y) : 1.0 - fract(r.y);
            return r;
        }
        return clamp(uv, 0.0, 1.0);
    }
    float isInBounds(float2 uv) {
        return step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
    }
    float2 warpFisheye(float2 p, float amount, float radius, float softness) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float normDist = dist / max(r, 0.00001);
        float power = 1.0 + amt * 2.0;
        float warpedDist = pow(normDist, power) * r;
        float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
        float finalDist = mix(dist, warpedDist, blend);
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpAntiFisheye(float2 p, float amount, float radius, float softness) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float normDist = dist / max(r, 0.00001);
        float power = 1.0 / max(1.0 + amt * 2.0, 0.01);
        float warpedDist = pow(normDist, power) * r;
        float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
        float finalDist = mix(dist, warpedDist, blend);
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpBarrel(float2 p, float k1v, float k2v, float k3v) {
        float r2 = dot(p, p);
        float r4 = r2 * r2;
        float r6 = r4 * r2;
        float distortion = 1.0 + k1v * r2 + k2v * r4 + k3v * r6;
        return p * distortion;
    }
    float2 warpPincushion(float2 p, float amount) {
        float dist = length(p);
        if (dist < 0.00001) return p;
        float amt = -amount / 100.0;
        float r2 = dot(p, p);
        float distortion = 1.0 + amt * r2 + amt * amt * r2 * r2;
        return p * distortion;
    }
    float2 warpBulge(float2 p, float amount, float radius, float softness) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float normDist = dist / max(r, 0.00001);
        float bulge = 1.0 + amt * (1.0 - normDist * normDist);
        bulge = max(bulge, 0.01);
        float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
        float scale = mix(1.0, bulge, blend);
        return p * scale;
    }
    float2 warpBullseye(float2 p, float amount, float radius) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float normDist = dist / max(r, 0.00001);
        float ringDist = sin(normDist * 3.14159265359 * 3.0) * amt * 0.3;
        float finalDist = dist + ringDist * r;
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpUpperShell(float2 p, float amount, float radius, float softness) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float topMask = smoothstep(-0.1, 0.1, -p.y);
        float normDist = dist / max(r, 0.00001);
        float power = 1.0 + amt * 2.0 * topMask;
        float warpedDist = pow(normDist, power) * r;
        float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
        float finalDist = mix(dist, warpedDist, blend * topMask);
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpLowerShell(float2 p, float amount, float radius, float softness) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float amt = amount / 100.0;
        float bottomMask = smoothstep(-0.1, 0.1, p.y);
        float normDist = dist / max(r, 0.00001);
        float power = 1.0 + amt * 2.0 * bottomMask;
        float warpedDist = pow(normDist, power) * r;
        float blend = smoothstep(r, r * (1.0 - softness * 0.01), dist);
        float finalDist = mix(dist, warpedDist, blend * bottomMask);
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpSpherize(float2 p, float amount, float radius) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001 || dist > r) return p;
        float amt = amount / 100.0;
        float normDist = dist / r;
        float z = sqrt(max(1.0 - normDist * normDist, 0.0));
        float sphereDist = asin(normDist) / max(3.14159265359 * 0.5, 0.00001);
        float finalDist = mix(normDist, sphereDist, amt) * r;
        return p * (finalDist / max(dist, 0.00001));
    }
    float2 warpTwirl(float2 p, float angle, float radius) {
        float dist = length(p);
        float r = radius * 0.5;
        if (dist < 0.00001) return p;
        float angRad = angle * 3.14159265359 / 180.0;
        float normDist = clamp(dist / max(r, 0.00001), 0.0, 1.0);
        float twirlAmt = angRad * (1.0 - normDist);
        float cs = cos(twirlAmt);
        float sn = sin(twirlAmt);
        return float2(p.x * cs - p.y * sn, p.x * sn + p.y * cs);
    }
    float2 warpWave(float2 p, float amp, float freq, float phase, float angle, float amzLocal_time) {
        float angRad = angle * 3.14159265359 / 180.0;
        float phaseRad = phase * 3.14159265359 / 180.0;
        float2 dir = float2(cos(angRad), sin(angRad));
        float2 perp = float2(-dir.y, dir.x);
        float projection = dot(p, dir);
        float waveVal = sin(projection * freq * 6.28318530718 + phaseRad + amzLocal_time * 6.28318530718) * amp * 0.01;
        return p + perp * waveVal;
    }
    float2 warpRipple(float2 p, float amp, float freq, float phase, float decay, float amzLocal_time) {
        float dist = length(p);
        if (dist < 0.00001) return p;
        float phaseRad = phase * 3.14159265359 / 180.0;
        float decayFactor = 1.0;
        if (decay > 0.5) {
            decayFactor = exp(-dist * decay * 0.1);
        }
        float rippleVal = sin(dist * freq * 6.28318530718 - phaseRad - amzLocal_time * 6.28318530718) * amp * 0.01 * decayFactor;
        float2 dir = p / dist;
        return p + dir * rippleVal;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float em = float(int(amzp_edgeMode));
        float wm = float(int(amzp_warpMode));
        float2 imgSize = getTexSize((screen.zw/1.0));
        float aspect = imgSize.x / max(imgSize.y, 1.0);
        float4 original = amzTexture(0, uv);
        float3 baseRGB = original.rgb;
        float2 center = float2(0.5 + amzp_warpCenter.x, 0.5 + amzp_warpCenter.y);
        float2 p = uv - center;
        p.x *= aspect * amzp_aspectX;
        p.y *= amzp_aspectY;
        float radius = amzp_warpRadius / 100.0;
        float softness = amzp_warpSoftness;
        float amt = amzp_warpAmount;
        float t = time;
        float2 warped = p;
        if (wm < 1.5) {
            warped = warpFisheye(p, amt, radius, softness);
        } else if (wm < 2.5) {
            warped = warpAntiFisheye(p, amt, radius, softness);
        } else if (wm < 3.5) {
            warped = warpBarrel(p, amzp_k1 + amt * 0.01, amzp_k2, amzp_k3);
        } else if (wm < 4.5) {
            warped = warpPincushion(p, amt);
        } else if (wm < 5.5) {
            warped = warpBulge(p, amt, radius, softness);
        } else if (wm < 6.5) {
            warped = warpBullseye(p, amt, radius);
        } else if (wm < 7.5) {
            warped = warpUpperShell(p, amt, radius, softness);
        } else if (wm < 8.5) {
            warped = warpLowerShell(p, amt, radius, softness);
        } else if (wm < 9.5) {
            warped = warpSpherize(p, amt, radius);
        } else if (wm < 10.5) {
            warped = warpTwirl(p, amzp_twirlAngle + amt, amzp_twirlRadius / 100.0);
        } else if (wm < 11.5) {
            warped = warpWave(p, amzp_waveAmplitude + abs(amt) * 0.5, amzp_waveFrequency, amzp_wavePhase, amzp_waveAngle, t * amzp_waveSpeed);
        } else {
            warped = warpRipple(p, amzp_rippleAmplitude + abs(amt) * 0.5, amzp_rippleFrequency, amzp_ripplePhase, amzp_rippleDecay, t * amzp_rippleSpeed);
        }
        if (abs(amzp_bendX) > 0.5 || abs(amzp_bendY) > 0.5 || abs(amzp_bendUniform) > 0.5) {
            float bx = (amzp_bendX + amzp_bendUniform) / 100.0;
            float by = (amzp_bendY + amzp_bendUniform) / 100.0;
            warped.x += bx * warped.y * warped.y;
            warped.y += by * warped.x * warped.x;
        }
        if (wm > 3.5 || wm < 2.5) {
            if (abs(amzp_k1) > 0.00001 || abs(amzp_k2) > 0.00001 || abs(amzp_k3) > 0.00001) {
                float r2 = dot(warped, warped);
                float r4 = r2 * r2;
                float r6 = r4 * r2;
                float kDist = 1.0 + amzp_k1 * r2 + amzp_k2 * r4 + amzp_k3 * r6;
                warped *= kDist;
            }
        }
        warped.x /= aspect * amzp_aspectX;
        warped.y /= amzp_aspectY;
        float2 warpedUV = warped + center;
        float chromaStr = amzp_chromaWarp / 100.0;
        float3 result;
        if (chromaStr > 0.00001) {
            float2 pR = uv - center;
            pR.x *= aspect * amzp_aspectX;
            pR.y *= amzp_aspectY;
            float2 pB = pR;
            float rAmt = amt * (1.0 + chromaStr * 0.3);
            float bAmt = amt * (1.0 - chromaStr * 0.3);
            float2 warpedR = pR;
            float2 warpedB = pB;
            if (wm < 1.5) {
                warpedR = warpFisheye(pR, rAmt, radius, softness);
                warpedB = warpFisheye(pB, bAmt, radius, softness);
            } else if (wm < 2.5) {
                warpedR = warpAntiFisheye(pR, rAmt, radius, softness);
                warpedB = warpAntiFisheye(pB, bAmt, radius, softness);
            } else if (wm < 3.5) {
                warpedR = warpBarrel(pR, amzp_k1 + rAmt * 0.01, amzp_k2, amzp_k3);
                warpedB = warpBarrel(pB, amzp_k1 + bAmt * 0.01, amzp_k2, amzp_k3);
            } else if (wm < 5.5) {
                warpedR = warpBulge(pR, rAmt, radius, softness);
                warpedB = warpBulge(pB, bAmt, radius, softness);
            } else {
                warpedR = warped;
                warpedB = warped;
            }
            if (abs(amzp_bendX) > 0.5 || abs(amzp_bendY) > 0.5 || abs(amzp_bendUniform) > 0.5) {
                float bx = (amzp_bendX + amzp_bendUniform) / 100.0;
                float by = (amzp_bendY + amzp_bendUniform) / 100.0;
                warpedR.x += bx * warpedR.y * warpedR.y;
                warpedR.y += by * warpedR.x * warpedR.x;
                warpedB.x += bx * warpedB.y * warpedB.y;
                warpedB.y += by * warpedB.x * warpedB.x;
            }
            warpedR.x /= aspect * amzp_aspectX;
            warpedR.y /= amzp_aspectY;
            warpedB.x /= aspect * amzp_aspectX;
            warpedB.y /= amzp_aspectY;
            float2 uvR = warpedR + center;
            float2 uvB = warpedB + center;
            float inR = (em < 1.5) ? isInBounds(uvR) : 1.0;
            float inG = (em < 1.5) ? isInBounds(warpedUV) : 1.0;
            float inB = (em < 1.5) ? isInBounds(uvB) : 1.0;
            uvR = applyEdge(uvR, em); uvR = clamp(uvR, 0.0, 1.0);
            float2 uvG = applyEdge(warpedUV, em); uvG = clamp(uvG, 0.0, 1.0);
            uvB = applyEdge(uvB, em); uvB = clamp(uvB, 0.0, 1.0);
            result.r = amzTexture(0, uvR).r * inR;
            result.g = amzTexture(0, uvG).g * inG;
            result.b = amzTexture(0, uvB).b * inB;
        } else {
            float inBounds = (em < 1.5) ? isInBounds(warpedUV) : 1.0;
            warpedUV = applyEdge(warpedUV, em);
            warpedUV = clamp(warpedUV, 0.0, 1.0);
            result = amzTexture(0, warpedUV).rgb * inBounds;
        }
        result = mix(baseRGB, result, amzp_globalMix);
        result = clamp(result, 0.0, 1.0);
        amzOutput = float4(result, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

